import React from "react";
import {
  Document,
  Page,
  View,
  Text,
  Image,
  StyleSheet,
  Font,
} from "@react-pdf/renderer";
import type { Quotation, AgencySettings, Client } from "@/lib/quotation-models";

Font.register({
  family: "Helvetica",
  fonts: [],
});

const BLACK = "#111111";
const WHITE = "#ffffff";
const GRAY = "#555555";
const LIGHT_GRAY = "#f8f8f8";
const BORDER_GRAY = "#dddddd";
const DARK_GRAY = "#333333";

const s = StyleSheet.create({
  page: { backgroundColor: WHITE, fontFamily: "Helvetica", fontSize: 9, color: BLACK },
  darkPage: { backgroundColor: BLACK, fontFamily: "Helvetica", fontSize: 9, color: WHITE },

  // Header
  header: { flexDirection: "row", alignItems: "center", justifyContent: "space-between", paddingHorizontal: 36, paddingVertical: 10, borderBottomWidth: 2, borderBottomColor: BLACK, borderBottomStyle: "solid", marginBottom: 16 },
  darkHeader: { flexDirection: "row", alignItems: "center", justifyContent: "space-between", paddingHorizontal: 36, paddingVertical: 10, borderBottomWidth: 2, borderBottomColor: WHITE, borderBottomStyle: "solid", marginBottom: 16 },
  headerLogo: { width: 80, height: 24, objectFit: "contain" },
  headerRight: { alignItems: "flex-end" },
  headerClient: { fontSize: 8, fontFamily: "Helvetica-Bold", textTransform: "uppercase", letterSpacing: 0.8 },
  headerDate: { fontSize: 6.5, color: GRAY, marginTop: 2 },
  headerDateDark: { fontSize: 6.5, color: "#aaaaaa", marginTop: 2 },

  // Page content
  body: { paddingHorizontal: 36, paddingBottom: 24, flex: 1 },

  // Page number
  pageNum: { position: "absolute", bottom: 12, right: 36, fontSize: 7, color: "#aaaaaa", fontFamily: "Helvetica-Bold", textTransform: "uppercase" },

  // Section heading
  sectionHeadWrap: { flexDirection: "row", alignItems: "center", marginBottom: 10, marginTop: 4 },
  sectionBar: { width: 3, height: 16, backgroundColor: BLACK, marginRight: 8 },
  sectionTitle: { fontSize: 10, fontFamily: "Helvetica-Bold", textTransform: "uppercase", letterSpacing: 0.8, color: BLACK },
  sectionTitleDark: { fontSize: 10, fontFamily: "Helvetica-Bold", textTransform: "uppercase", letterSpacing: 0.8, color: WHITE },

  // Table
  tableHeader: { flexDirection: "row", backgroundColor: BLACK },
  tableHeaderCell: { paddingVertical: 6, paddingHorizontal: 6, fontSize: 7, fontFamily: "Helvetica-Bold", textTransform: "uppercase", letterSpacing: 0.6, color: WHITE },
  tableRow: { flexDirection: "row", borderBottomWidth: 0.5, borderBottomColor: BORDER_GRAY, borderBottomStyle: "solid" },
  tableRowAlt: { backgroundColor: LIGHT_GRAY },
  tableCell: { paddingVertical: 5, paddingHorizontal: 6, fontSize: 8 },

  // Boxes
  bordered: { borderWidth: 1.5, borderColor: BLACK, borderStyle: "solid", padding: 14 },
  darkBox: { borderWidth: 1.5, borderColor: DARK_GRAY, borderStyle: "solid", padding: 14, backgroundColor: "#1e1e1e" },

  // Labels
  label: { fontSize: 6.5, fontFamily: "Helvetica-Bold", textTransform: "uppercase", letterSpacing: 0.8, color: GRAY, marginBottom: 3 },
  labelDark: { fontSize: 6.5, fontFamily: "Helvetica-Bold", textTransform: "uppercase", letterSpacing: 0.8, color: "#666666", marginBottom: 3 },
  value: { fontSize: 9, fontFamily: "Helvetica-Bold", color: BLACK },
  valueDark: { fontSize: 9, fontFamily: "Helvetica-Bold", color: WHITE },
});

function PageHeader({ clientName, generatedAt, dark = false }: { clientName: string; generatedAt: string; dark?: boolean }) {
  return (
    <View style={dark ? s.darkHeader : s.header}>
      <Image style={s.headerLogo} src={dark ? "/assets/images/Logo_Color_Name_Large.png" : "/assets/images/logo-transparent.png"} />
      <View style={s.headerRight}>
        <Text style={[s.headerClient, dark ? { color: WHITE } : {}]}>{clientName}</Text>
        <Text style={dark ? s.headerDateDark : s.headerDate}>Generated: {generatedAt}</Text>
      </View>
    </View>
  );
}

function PageNum({ n, total }: { n: number; total: number }) {
  return <Text style={s.pageNum} fixed={false}>{n} / {total}</Text>;
}

function SectionHead({ title, dark = false }: { title: string; dark?: boolean }) {
  return (
    <View style={s.sectionHeadWrap}>
      <View style={[s.sectionBar, dark ? { backgroundColor: WHITE } : {}]} />
      <Text style={dark ? s.sectionTitleDark : s.sectionTitle}>{title}</Text>
    </View>
  );
}

interface Props {
  quotation: Quotation;
  client: Client | null;
  settings: AgencySettings | null;
}

export function QuotationPdfDocument({ quotation, client, settings }: Props) {
  const clientName = (client?.businessName || client?.name || "Valued Client").toUpperCase();
  const generatedAt = new Date().toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" });
  const formattedDate = new Date(quotation.date || Date.now()).toLocaleDateString("en-GB", { day: "2-digit", month: "long", year: "numeric" }).toUpperCase();
  const grandTotal = (quotation.services || []).reduce((s, i) => s + i.price * i.qty, 0);
  const agencyName = (settings?.name || "PIXELATE NEST").toUpperCase();

  let totalPages = 4; // cover + about + client + deliverables+services
  if (quotation.scope?.length) totalPages++;
  totalPages++; // timeline
  if (quotation.modules?.length) totalPages++;
  totalPages++; // notes+terms+sig

  const terms: string[] = settings?.terms?.length
    ? settings.terms
    : [
        "Payment terms: 50% advance, 50% on completion",
        "Project timeline is subject to timely feedback and approvals",
        "Revisions beyond agreed scope will be charged separately",
        "All deliverables remain property of agency until full payment",
        "Client must provide necessary content and assets on time",
      ];

  return (
    <Document>

      {/* ── P1: Cover ── */}
      <Page size="A4" style={s.page}>
        {/* Top accent bar */}
        <View style={{ height: 5, backgroundColor: BLACK }} />

        <View style={{ flex: 1, alignItems: "center", justifyContent: "center", paddingHorizontal: 48 }}>
          <Image style={{ width: 120, height: 36, objectFit: "contain", marginBottom: 28 }} src="/assets/images/logo-transparent.png" />

          {/* Quote ID badge */}
          <View style={{ backgroundColor: BLACK, paddingHorizontal: 16, paddingVertical: 4, marginBottom: 16 }}>
            <Text style={{ color: WHITE, fontSize: 8, fontFamily: "Helvetica-Bold", textTransform: "uppercase", letterSpacing: 1.2 }}>
              {quotation.quoteId || "QUOTATION"}
            </Text>
          </View>

          <Text style={{ fontSize: 28, fontFamily: "Helvetica-Bold", color: BLACK, textTransform: "uppercase", letterSpacing: -0.5, textAlign: "center", marginBottom: 10 }}>
            {quotation.title || "PROJECT QUOTATION"}
          </Text>

          {quotation.subtitle && (
            <Text style={{ fontSize: 12, color: GRAY, textAlign: "center", marginBottom: 20 }}>{quotation.subtitle}</Text>
          )}

          <View style={{ borderTopWidth: 2, borderTopColor: "#044bab", borderTopStyle: "solid", borderBottomWidth: 2, borderBottomColor: BLACK, borderBottomStyle: "solid", paddingVertical: 14, marginTop: 20, marginBottom: 20, width: "80%", alignItems: "center" }}>
            <Text style={{ fontSize: 7.5, fontFamily: "Helvetica-Bold", textTransform: "uppercase", letterSpacing: 0.8, color: GRAY, marginBottom: 6 }}>Prepared For</Text>
            <Text style={{ fontSize: 20, fontFamily: "Helvetica-Bold", color: BLACK, textTransform: "uppercase" }}>{clientName}</Text>
          </View>

          <Text style={{ fontSize: 9, color: GRAY, fontFamily: "Helvetica-Bold", textTransform: "uppercase", letterSpacing: 0.6 }}>{formattedDate}</Text>
        </View>

        {/* Bottom accent bar */}
        <View style={{ height: 5, backgroundColor: BLACK }} />
      </Page>

      {/* ── P2: About ── */}
      <Page size="A4" style={s.darkPage}>
        <PageHeader clientName={clientName} generatedAt={generatedAt} dark />

        <View style={s.body}>
          <Text style={{ fontSize: 20, fontFamily: "Helvetica-Bold", color: WHITE, textTransform: "uppercase", marginBottom: 4 }}>{agencyName}</Text>
          <Text style={{ fontSize: 7.5, color: "#aaaaaa", fontFamily: "Helvetica-Bold", textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 14, paddingBottom: 10, borderBottomWidth: 1, borderBottomColor: "#444444", borderBottomStyle: "solid" }}>
            Creative Software &amp; Digital Solutions
          </Text>

          {settings?.aboutUs && (
            <View style={{ marginBottom: 14 }}>
              <SectionHead title="About Us" dark />
              <Text style={{ fontSize: 8.5, color: "#cccccc", lineHeight: 1.6 }}>{settings.aboutUs}</Text>
            </View>
          )}

          {/* Mission / Vision / Goal */}
          <View style={{ flexDirection: "row", gap: 8, marginBottom: 14 }}>
            {[
              { label: "Mission", text: settings?.mission || "To deliver exceptional digital solutions that exceed client expectations." },
              { label: "Vision", text: settings?.vision || "To be the leading creative digital agency transforming businesses globally." },
              { label: "Goal", text: settings?.goal || "To empower 1000+ businesses with cutting-edge digital solutions." },
            ].map(({ label, text }) => (
              <View key={label} style={[s.darkBox, { flex: 1 }]}>
                <Text style={{ fontSize: 7.5, fontFamily: "Helvetica-Bold", textTransform: "uppercase", letterSpacing: 0.8, color: WHITE, marginBottom: 6 }}>{label}</Text>
                <Text style={{ fontSize: 7.5, color: "#bbbbbb", lineHeight: 1.5 }}>{text}</Text>
              </View>
            ))}
          </View>

          {/* Contact */}
          <View style={[s.darkBox, { borderColor: DARK_GRAY }]}>
            <SectionHead title="Contact" dark />
            <View style={{ flexDirection: "row", flexWrap: "wrap" }}>
              {[
                { label: "Email", value: settings?.email || "info@pixelatenest.com" },
                { label: "Phone", value: settings?.phone || "+91 XXXXXXXXXX" },
                { label: "Address", value: settings?.address || "Kala Bhawan, Muzaffarpur, Bihar" },
                { label: "Website", value: settings?.website || "www.pixelatenest.com" },
              ].map(({ label, value }, i) => (
                <View key={label} style={{ width: "50%", paddingRight: 8, marginBottom: i < 2 ? 10 : 0 }}>
                  <Text style={s.labelDark}>{label}</Text>
                  <Text style={s.valueDark}>{value}</Text>
                </View>
              ))}
            </View>
          </View>
        </View>

        <PageNum n={1} total={totalPages} />
      </Page>

      {/* ── P3: Client Information ── */}
      <Page size="A4" style={s.page}>
        <PageHeader clientName={clientName} generatedAt={generatedAt} />
        <View style={s.body}>
          <SectionHead title="Client Information" />
          <View style={[s.bordered, { marginBottom: 16 }]}>
            <View style={{ flexDirection: "row", marginBottom: client?.address ? 10 : 0 }}>
              {[
                { label: "Client Name", value: client?.name || "N/A" },
                { label: "Email", value: client?.email || "N/A" },
                { label: "Phone", value: client?.phone || "N/A" },
              ].map(({ label, value }) => (
                <View key={label} style={{ flex: 1, paddingRight: 8 }}>
                  <Text style={s.label}>{label}</Text>
                  <Text style={s.value}>{value}</Text>
                </View>
              ))}
            </View>
            {client?.address && (
              <View>
                <Text style={s.label}>Address</Text>
                <Text style={s.value}>{client.address}</Text>
              </View>
            )}
          </View>

          {quotation.objective && (
            <View style={{ marginBottom: 14 }}>
              <SectionHead title="Project Objective" />
              <Text style={{ fontSize: 8.5, color: DARK_GRAY, lineHeight: 1.6 }}>{quotation.objective}</Text>
            </View>
          )}

          {quotation.purpose && (
            <View style={{ marginBottom: 14 }}>
              <SectionHead title="Purpose" />
              <Text style={{ fontSize: 8.5, color: DARK_GRAY, lineHeight: 1.6 }}>{quotation.purpose}</Text>
            </View>
          )}
        </View>
        <PageNum n={2} total={totalPages} />
      </Page>

      {/* ── P4 (cond): Scope of Work ── */}
      {quotation.scope && quotation.scope.length > 0 && (
        <Page size="A4" style={s.page}>
          <PageHeader clientName={clientName} generatedAt={generatedAt} />
          <View style={s.body}>
            <SectionHead title="Scope of Work" />
            <View style={{ borderWidth: 1.5, borderColor: BLACK, borderStyle: "solid" }}>
              {quotation.scope.map((item, idx) => (
                <View key={idx} style={[s.tableRow, idx % 2 !== 0 ? s.tableRowAlt : {}, { flexDirection: "row", alignItems: "flex-start", paddingVertical: 7, paddingHorizontal: 10 }]}>
                  <Text style={{ fontSize: 8, fontFamily: "Helvetica-Bold", color: BLACK, marginRight: 8, minWidth: 18 }}>{String(idx + 1).padStart(2, "0")}.</Text>
                  <Text style={{ fontSize: 8.5, color: DARK_GRAY, flex: 1, lineHeight: 1.5 }}>{item}</Text>
                </View>
              ))}
            </View>
          </View>
          <PageNum n={3} total={totalPages} />
        </Page>
      )}

      {/* ── P5: Deliverables + Services ── */}
      <Page size="A4" style={s.page}>
        <PageHeader clientName={clientName} generatedAt={generatedAt} />
        <View style={s.body}>
          {quotation.deliverables && quotation.deliverables.length > 0 && (
            <View style={{ marginBottom: 16 }}>
              <SectionHead title="Deliverables" />
              <View style={{ borderWidth: 1.5, borderColor: BLACK, borderStyle: "solid" }}>
                {quotation.deliverables.map((item, idx) => (
                  <View key={idx} style={[s.tableRow, idx % 2 !== 0 ? s.tableRowAlt : {}, { flexDirection: "row", alignItems: "flex-start", paddingVertical: 6, paddingHorizontal: 10 }]}>
                    <View style={{ width: 8, height: 8, borderWidth: 1, borderColor: BLACK, borderStyle: "solid", marginRight: 8, marginTop: 1 }} />
                    <Text style={{ fontSize: 8.5, color: DARK_GRAY, flex: 1, lineHeight: 1.5 }}>{item}</Text>
                  </View>
                ))}
              </View>
            </View>
          )}

          {quotation.services && quotation.services.length > 0 && (
            <View>
              <SectionHead title="Services Breakdown" />
              <View style={{ borderWidth: 1.5, borderColor: BLACK, borderStyle: "solid" }}>
                <View style={s.tableHeader}>
                  <Text style={[s.tableHeaderCell, { flex: 4 }]}>Service</Text>
                  <Text style={[s.tableHeaderCell, { width: 40, textAlign: "center" }]}>Qty</Text>
                  <Text style={[s.tableHeaderCell, { width: 70, textAlign: "right" }]}>Price</Text>
                  <Text style={[s.tableHeaderCell, { width: 70, textAlign: "right" }]}>Total</Text>
                </View>
                {quotation.services.map((item, idx) => {
                  const total = item.price * item.qty;
                  return (
                    <View key={idx} style={[s.tableRow, idx % 2 !== 0 ? s.tableRowAlt : {}]}>
                      <Text style={[s.tableCell, { flex: 4, fontFamily: "Helvetica-Bold" }]}>{item.serviceName}</Text>
                      <Text style={[s.tableCell, { width: 40, textAlign: "center" }]}>{item.qty}</Text>
                      <Text style={[s.tableCell, { width: 70, textAlign: "right" }]}>Rs.{item.price.toLocaleString("en-IN")}</Text>
                      <Text style={[s.tableCell, { width: 70, textAlign: "right", fontFamily: "Helvetica-Bold" }]}>Rs.{total.toLocaleString("en-IN")}</Text>
                    </View>
                  );
                })}
                <View style={{ flexDirection: "row", backgroundColor: BLACK, paddingVertical: 8, paddingHorizontal: 6 }}>
                  <Text style={{ flex: 1, color: WHITE, fontSize: 8, fontFamily: "Helvetica-Bold", textTransform: "uppercase", textAlign: "right", paddingRight: 6 }}>Grand Total</Text>
                  <Text style={{ width: 70, color: WHITE, fontSize: 12, fontFamily: "Helvetica-Bold", textAlign: "right" }}>Rs.{grandTotal.toLocaleString("en-IN")}</Text>
                </View>
              </View>
            </View>
          )}
        </View>
        <PageNum n={quotation.scope?.length ? 4 : 3} total={totalPages} />
      </Page>

      {/* ── P6: Timeline ── */}
      <Page size="A4" style={s.page}>
        <PageHeader clientName={clientName} generatedAt={generatedAt} />
        <View style={s.body}>
          {quotation.timeline && quotation.timeline.length > 0 && (
            <View>
              <SectionHead title="Project Timeline" />
              <View style={{ borderWidth: 1.5, borderColor: BLACK, borderStyle: "solid" }}>
                <View style={s.tableHeader}>
                  <Text style={[s.tableHeaderCell, { width: 100 }]}>Phase</Text>
                  <Text style={[s.tableHeaderCell, { flex: 1 }]}>Description</Text>
                  <Text style={[s.tableHeaderCell, { width: 70, textAlign: "right" }]}>Duration</Text>
                </View>
                {quotation.timeline.map((item, idx) => (
                  <View key={idx} style={[s.tableRow, idx % 2 !== 0 ? s.tableRowAlt : {}]}>
                    <Text style={[s.tableCell, { width: 100, fontFamily: "Helvetica-Bold" }]}>{item.phase}</Text>
                    <Text style={[s.tableCell, { flex: 1, color: DARK_GRAY }]}>{item.description}</Text>
                    <Text style={[s.tableCell, { width: 70, textAlign: "right", fontFamily: "Helvetica-Bold" }]}>{item.duration}</Text>
                  </View>
                ))}
              </View>
            </View>
          )}
        </View>
        <PageNum n={quotation.scope?.length ? 5 : 4} total={totalPages} />
      </Page>

      {/* ── P7 (cond): Modules ── */}
      {quotation.modules && quotation.modules.length > 0 && (
        <Page size="A4" style={s.page}>
          <PageHeader clientName={clientName} generatedAt={generatedAt} />
          <View style={s.body}>
            <SectionHead title="Modules & Features" />
            <View style={{ flexDirection: "row", flexWrap: "wrap", gap: 8 }}>
              {quotation.modules.map((mod, idx) => (
                <View key={idx} style={[s.bordered, { width: "48%", marginBottom: 4 }]}>
                  <View style={{ flexDirection: "row", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 6 }}>
                    <Text style={{ fontFamily: "Helvetica-Bold", fontSize: 9, color: BLACK, flex: 1, marginRight: 6 }}>{mod.moduleName}</Text>
                    <View style={{ backgroundColor: mod.status === "Completed" ? BLACK : mod.status === "Ongoing" ? "#555555" : "#dddddd", paddingHorizontal: 5, paddingVertical: 2 }}>
                      <Text style={{ fontSize: 6, fontFamily: "Helvetica-Bold", textTransform: "uppercase", color: mod.status === "Completed" || mod.status === "Ongoing" ? WHITE : BLACK }}>{mod.status}</Text>
                    </View>
                  </View>
                  <Text style={{ fontSize: 7.5, color: GRAY, lineHeight: 1.5 }}>{mod.description}</Text>
                </View>
              ))}
            </View>
          </View>
          <PageNum n={totalPages - 1} total={totalPages} />
        </Page>
      )}

      {/* ── P Last: Notes + Terms + Signature ── */}
      <Page size="A4" style={s.page}>
        <PageHeader clientName={clientName} generatedAt={generatedAt} />
        <View style={[s.body, { justifyContent: "space-between" }]}>
          <View>
            {(quotation.notes || quotation.paymentTerms) && (
              <View style={{ marginBottom: 14 }}>
                <SectionHead title="Additional Information" />
                <View style={s.bordered}>
                  {quotation.paymentTerms && (
                    <View style={{ marginBottom: quotation.notes ? 12 : 0 }}>
                      <Text style={s.label}>Payment Terms</Text>
                      <Text style={{ fontSize: 8.5, color: DARK_GRAY, lineHeight: 1.6 }}>{quotation.paymentTerms}</Text>
                    </View>
                  )}
                  {quotation.notes && (
                    <View>
                      <Text style={s.label}>Notes</Text>
                      <Text style={{ fontSize: 8.5, color: DARK_GRAY, lineHeight: 1.6 }}>{quotation.notes}</Text>
                    </View>
                  )}
                </View>
              </View>
            )}

            <View style={{ marginBottom: 14 }}>
              <SectionHead title="Terms & Conditions" />
              <View style={s.bordered}>
                {terms.map((term, idx) => (
                  <View key={idx} style={{ flexDirection: "row", marginBottom: 6 }}>
                    <Text style={{ fontSize: 8, fontFamily: "Helvetica-Bold", color: BLACK, marginRight: 6, minWidth: 14 }}>{idx + 1}.</Text>
                    <Text style={{ fontSize: 8.5, color: DARK_GRAY, flex: 1, lineHeight: 1.5 }}>{term}</Text>
                  </View>
                ))}
              </View>
            </View>
          </View>

          {/* Signature */}
          <View>
            <View style={{ borderTopWidth: 2, borderTopColor: BLACK, borderTopStyle: "solid", paddingTop: 16, flexDirection: "row", gap: 32, marginBottom: 16 }}>
              <View style={{ flex: 1 }}>
                <Image style={{ height: 36, width: 100, objectFit: "contain", marginBottom: 6 }} src="/assets/images/sign.png" />
                <View style={{ borderTopWidth: 1.5, borderTopColor: BLACK, borderTopStyle: "solid", paddingTop: 6 }}>
                  <Text style={{ fontSize: 8, fontFamily: "Helvetica-Bold", textTransform: "uppercase", letterSpacing: 0.6 }}>Authorized Signatory</Text>
                  <Text style={{ fontSize: 8, color: GRAY, marginTop: 2 }}>{settings?.name || "Kalahanu Tech Studios LLP"}</Text>
                </View>
              </View>
              <View style={{ flex: 1 }}>
                <View style={{ height: 36, marginBottom: 6 }} />
                <View style={{ borderTopWidth: 1.5, borderTopColor: BLACK, borderTopStyle: "solid", paddingTop: 6 }}>
                  <Text style={{ fontSize: 8, fontFamily: "Helvetica-Bold", textTransform: "uppercase", letterSpacing: 0.6 }}>Client Signature</Text>
                  <Text style={{ fontSize: 8, color: GRAY, marginTop: 2 }}>{clientName}</Text>
                  <Text style={{ fontSize: 7, color: "#999999", marginTop: 3 }}>Date: __________________</Text>
                </View>
              </View>
            </View>

            {/* Footer */}
            <View style={{ borderTopWidth: 0.5, borderTopColor: BORDER_GRAY, borderTopStyle: "solid", paddingTop: 8, alignItems: "center" }}>
              <Text style={{ fontSize: 7.5, color: GRAY, fontFamily: "Helvetica-Bold", marginBottom: 3 }}>
                {settings?.footerText || `© 2026 ${settings?.name || "Kalahanu Tech Studios LLP"}. All Rights Reserved.`}
              </Text>
              <Text style={{ fontSize: 7, color: "#999999" }}>
                {settings?.phone || "+91 84069 12345"}  |  {settings?.email || "support@pixelatenest.com"}  |  {settings?.website || "www.pixelatenest.com"}
              </Text>
            </View>
          </View>
        </View>

        <PageNum n={totalPages} total={totalPages} />
      </Page>

    </Document>
  );
}
